from queueing import payload

def submit(owner, enqueue, batch_size=20):
    if isinstance(batch_size, bool) or not isinstance(batch_size, int):
        raise ValueError("batch_size must be an integer between 1 and 100")
    if not 1 <= batch_size <= 100:
        raise ValueError("batch_size must be an integer between 1 and 100")
    return enqueue(payload(owner, batch_size))

def execute(task, process):
    batch_size = task.get("batch_size", 20)
    return process(task["owner"], batch_size)

import api
from api import submit


def test_legacy_submit_valid():
    seen = {}
    def enqueue(payload_dict):
        seen["owner"] = payload_dict["owner"]
        seen["batch_size"] = payload_dict.get("batch_size", 20)
        return payload_dict
    submit("alice", enqueue)
    assert seen["owner"] == "alice"
    assert seen["batch_size"] == 20


def test_custom_batch_size():
    seen = {}
    def enqueue(payload_dict):
        seen["payload"] = payload_dict
        return payload_dict
    submit("bob", enqueue, batch_size=7)
    assert seen["payload"] == {"owner": "bob", "batch_size": 7}


def test_invalid_batch_size_raises_before_enqueue():
    calls = []
    def enqueue(payload_dict):
        calls.append(payload_dict)
        raise AssertionError("enqueue should not be called")
    for bad in (0, 101, 2.5, True, "10"):
        try:
            submit("carol", enqueue, batch_size=bad)
        except ValueError:
            pass
        else:
            raise AssertionError("expected ValueError for %r" % (bad,))
    assert calls == []


def test_bool_rejected():
    def enqueue(payload_dict):
        raise AssertionError("enqueue should not be called")
    try:
        submit("dave", enqueue, batch_size=True)
    except ValueError:
        pass
    else:
        raise AssertionError("expected ValueError for True")


